// Define the Complex struct as described: 32-bit integer real and imaginary parts.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Complex {
    real: i32,
    imag: i32,
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // Machine epsilon fixed as 2 (given in the problem).
    let epsilon = 2;
    // Calculate threshold = tol * epsilon as i64 to avoid overflow.
    let threshold = (tol as i64) * (epsilon as i64);

    // First, check if every element's imaginary part is "close to zero".
    // Imag part is "close to zero" if abs(imag) <= threshold.
    // Use i64 for absolute value to avoid potential overflow on i32::MIN.
    let all_close = arr.iter().all(|c| (c.imag as i64).abs() <= threshold);

    if all_close {
        // Next, check if all imaginary parts are exactly zero
        // to decide if we must return input unchanged or modified.
        let all_zero = arr.iter().all(|c| c.imag == 0);

        if all_zero {
            // The array is already real — return as is.
            arr
        } else {
            // All imaginary parts are close to zero but not all zero
            // Return a new vector with imag set to 0, real unchanged.
            arr.into_iter()
                .map(|c| Complex { real: c.real, imag: 0 })
                .collect()
        }
    } else {
        // Not all imaginary parts close to zero - return input unchanged.
        arr
    }
}